        const auto icon=qvariant_cast<QIcon>(index.data(Qt::DecorationRole));icon.paint(p,QRect(r.left()+8,r.top()+12,52,43));const auto kind=index.data(Qt::UserRole+1).toString();p->setFont(option.font);p->setPen(option.palette.color(QPalette::Text));p->drawText(QRect(r.left()+68,r.top()+8,r.width()-76,21),Qt::AlignVCenter,p->fontMetrics().elidedText(index.data().toString(),Qt::ElideRight,r.width()-76));p->setPen(kind=="Ad"?QColor("#45c58b"):option.palette.color(QPalette::PlaceholderText));p->drawText(QRect(r.left()+68,r.top()+29,r.width()-76,18),Qt::AlignVCenter,p->fontMetrics().elidedText(index.data(Qt::UserRole+2).toString(),Qt::ElideRight,r.width()-76));p->drawText(QRect(r.left()+68,r.top()+47,r.width()-76,17),Qt::AlignVCenter,index.data(Qt::UserRole+3).toString());p->restore();
