        QObject::connect(filter,&QTabBar::currentChanged,q,[this]{refreshSources();});QObject::connect(search,&QLineEdit::textChanged,q,[this]{refreshSources();});auto addSelected=[this]{if(auto *item=sources->currentItem())q->appendSource(item->data(Qt::UserRole+1).toString(),item->data(Qt::UserRole).toString());};QObject::connect(add,&QPushButton::clicked,q,addSelected);QObject::connect(sources,&QListWidget::itemDoubleClicked,q,[addSelected](QListWidgetItem*){addSelected();});QObject::connect(sources,&QListWidget::customContextMenuRequested,q,[this,addSelected](QPoint point){auto *item=sources->itemAt(point);if(!item)return;sources->setCurrentItem(item);QMenu menu(q);auto *action=menu.addAction(uiIcon("add"),"Put on plan timeline");if(menu.exec(sources->viewport()->mapToGlobal(point))==action)addSelected();});
